                function controller:SetText(newText)
                    mainLabel.Text = tostring(newText or '')
                    glowBack1.Text = mainLabel.Text
                    glowBack2.Text = mainLabel.Text
                end
                function controller:SetActive(isActive)
                    if isActive then
                        mainLabel.TextTransparency = 0
