                local n = 0
                local val = 0
                local count = 0

                for i = 1, #data do
                    local c = string.byte(data, i)
                    local v = map[c]

                    if v ~= nil then
                        val = val * 64 + v
                        count = count + 1

                        if count == 4 then
                            local b1 = math.floor(val / 65536) % 256
                            local b2 = math.floor(val / 256) % 256
                            local b3 = val % 256

