    do
        local function __modImpl()
            local UserInputService = game:GetService('UserInputService')
            local Theme = __DARKLUA_BUNDLE_MODULES.b()
            local Utility = __DARKLUA_BUNDLE_MODULES.c()
            local Scrollbar = {}

            function Scrollbar.Attach(scrollingFrame)
                if not scrollingFrame or not scrollingFrame:IsA('ScrollingFrame') then
                    return nil
                end

                scrollingFrame.ScrollBarThickness = 0

                local parent = scrollingFrame.Parent
                local barFrame = Utility.Create('Frame', {
                    Name = 'Win7VerticalScrollbar',
                    Parent = parent,
                    BackgroundColor3 = Color3.fromRGB(240, 240, 240),
                    Position = UDim2.new(1, -16, scrollingFrame.Position.Y.Scale, scrollingFrame.Position.Y.Offset),
                    Size = UDim2.new(0, 16, scrollingFrame.Size.Y.Scale, scrollingFrame.Size.Y.Offset),
                    ZIndex = scrollingFrame.ZIndex + 4,
                })

                Utility.AddStroke(barFrame, Color3.fromRGB(212, 216, 222), 1, 0, Enum.ApplyStrokeMode.Border)

                local trackGrad = Instance.new('UIGradient')

                trackGrad.Rotation = 0
                trackGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(228, 228, 228)),
                    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(242, 242, 242)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(234, 234, 234)),
                })
                trackGrad.Parent = barFrame

                local upBtn = Utility.Create('TextButton', {
                    Name = 'ScrollUpButton',
                    Parent = barFrame,
                    Position = UDim2.new(0, 0, 0, 0),
                    Size = UDim2.new(1, 0, 0, 16),
                    Text = '',
                    ZIndex = barFrame.ZIndex + 2,
                })

                Utility.BindWin7ButtonStates(upBtn, {CornerRadius = 1})
                Utility.CreateVectorChevron(upBtn, 'Up', Color3.fromRGB(56, 68, 82), upBtn.ZIndex + 2)

                local downBtn = Utility.Create('TextButton', {
                    Name = 'ScrollDownButton',
                    Parent = barFrame,
                    Position = UDim2.new(0, 0, 1, -16),
                    Size = UDim2.new(1, 0, 0, 16),
                    Text = '',
                    ZIndex = barFrame.ZIndex + 2,
                })

                Utility.BindWin7ButtonStates(downBtn, {CornerRadius = 1})
                Utility.CreateVectorChevron(downBtn, 'Down', Color3.fromRGB(56, 68, 82), downBtn.ZIndex + 2)

                local trackZone = Utility.Create('Frame', {
                    Name = 'ScrollThumbTrack',
                    Parent = barFrame,
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 0, 0, 16),
                    Size = UDim2.new(1, 0, 1, -32),
                    ZIndex = barFrame.ZIndex + 1,
                })
                local thumb = Utility.Create('TextButton', {
                    Name = 'ScrollThumb',
                    Parent = trackZone,
                    Position = UDim2.new(0, 1, 0, 0),
                    Size = UDim2.new(1, -2, 0.35, 0),
                    Text = '',
                    ZIndex = trackZone.ZIndex + 2,
                })

                Utility.BindWin7ButtonStates(thumb, {CornerRadius = 2})

                local gripLines = Utility.Create('Frame', {
                    Name = 'ThumbGripBars',
                    Parent = thumb,
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0.5, 0),
                    Size = UDim2.new(0, 6, 0, 7),
                    ZIndex = thumb.ZIndex + 2,
                })

                for i = 0, 2 do
                    Utility.Create('Frame', {
                        Name = 'GripLine_' .. tostring(i + 1),
                        Parent = gripLines,
                        BackgroundColor3 = Color3.fromRGB(118, 128, 140),
                        Position = UDim2.new(0, 0, 0, i * 3),
                        Size = UDim2.new(1, 0, 0, 1),
                        ZIndex = gripLines.ZIndex + 1,
                    })
                end

                local function getCanvasHeight()
                    local absCanvasY = scrollingFrame.AbsoluteCanvasSize and scrollingFrame.AbsoluteCanvasSize.Y

                    if absCanvasY and absCanvasY > 0 then
                        return absCanvasY
                    end

                    return scrollingFrame.CanvasSize.Y.Offset
                end
                local function syncThumbFromScroll()
                    local winH = math.max(scrollingFrame.AbsoluteSize.Y, 1)
                    local canvasH = math.max(getCanvasHeight(), winH)
                    local maxScroll = math.max(canvasH - winH, 0)

                    if maxScroll <= 2 then
                        thumb.Size = UDim2.new(1, -2, 1, 0)
                        thumb.Position = UDim2.new(0, 1, 0, 0)
                        gripLines.Visible = true

                        return
                    end

                    local ratio = math.clamp(winH / canvasH, 0.14, 0.92)
                    local scrollAlpha = math.clamp((scrollingFrame.CanvasPosition and scrollingFrame.CanvasPosition.Y or 0) / maxScroll, 0, 1)

                    thumb.Size = UDim2.new(1, -2, ratio, 0)
                    thumb.Position = UDim2.new(0, 1, scrollAlpha * (1 - ratio), 0)
                end

                upBtn.MouseButton1Click:Connect(function()
                    local curY = scrollingFrame.CanvasPosition and scrollingFrame.CanvasPosition.Y or 0

                    scrollingFrame.CanvasPosition = Vector2.new(0, math.max(0, curY - 36))

                    syncThumbFromScroll()
                end)
                downBtn.MouseButton1Click:Connect(function()
                    local curY = scrollingFrame.CanvasPosition and scrollingFrame.CanvasPosition.Y or 0
                    local winH = math.max(scrollingFrame.AbsoluteSize.Y, 1)
                    local maxScroll = math.max(getCanvasHeight() - winH, 0)

                    scrollingFrame.CanvasPosition = Vector2.new(0, math.min(maxScroll, curY + 36))

                    syncThumbFromScroll()
                end)

                local dragging = false
                local dragStartY = 0
                local startScrollY = 0

                thumb.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragging = true
                        dragStartY = input.Position.Y
                        startScrollY = scrollingFrame.CanvasPosition and scrollingFrame.CanvasPosition.Y or 0
                    end
                end)
                UserInputService.InputChanged:Connect(function(input)
                    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                        local trackH = math.max(trackZone.AbsoluteSize.Y, 1)
                        local winH = math.max(scrollingFrame.AbsoluteSize.Y, 1)
                        local maxScroll = math.max(getCanvasHeight() - winH, 0)
                        local dy = input.Position.Y - dragStartY
                        local scrollDelta = (dy / trackH) * maxScroll

                        scrollingFrame.CanvasPosition = Vector2.new(0, math.clamp(startScrollY + scrollDelta, 0, maxScroll))

                        syncThumbFromScroll()
                    end
                end)
                UserInputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragging = false
                    end
                end)
                scrollingFrame:GetPropertyChangedSignal('CanvasPosition'):Connect(syncThumbFromScroll)

                return {
                    BarFrame = barFrame,
                    UpButton = upBtn,
                    DownButton = downBtn,
                    Thumb = thumb,
                    Refresh = syncThumbFromScroll,
                }
            end

            return Scrollbar
        end

        function __DARKLUA_BUNDLE_MODULES.g()
            local v = __DARKLUA_BUNDLE_MODULES.cache.g

            if not v then
                v = {
                    c = __modImpl(),
                }
                __DARKLUA_BUNDLE_MODULES.cache.g = v
            end

            return v.c
        end
    end
    do
        local function __modImpl()
            local UserInputService = game:GetService('UserInputService')
            local Assets = __DARKLUA_BUNDLE_MODULES.a()
            local Theme = __DARKLUA_BUNDLE_MODULES.b()
            local Utility = __DARKLUA_BUNDLE_MODULES.c()
            local MenuBar = {}

            function MenuBar.CreatePopupMenu(
                parentGui,
                items,
                posUDim2,
                zBase,
                onItemSelected
            )
                zBase = zBase or 180
                items = items or {}

                local totalHeight = 4
                local maxRowWidth = 214

                for _, item in ipairs(items)do
                    if item.Separator or item == '-' then
                        totalHeight = totalHeight + 7
                    else
                        totalHeight = totalHeight + 22

                        local textLen = #tostring(item.Text or '')
                        local shortLen = (item.Shortcut and item.Shortcut ~= '') and (#tostring(item.Shortcut) + 3) or 0
                        local hasSub = (type(item.Items) == 'table' and #item.Items > 0) or (type(item.Submenu) == 'table' and #item.Submenu > 0)
                        local estW = 36 + (textLen * 7) + (shortLen * 7) + (hasSub and 18 or 14)

                        if estW > maxRowWidth then
                            maxRowWidth = estW
                        end
                    end
                end

                totalHeight = math.max(26, totalHeight)

                local menuWidth = math.clamp(maxRowWidth, 150, 268)
                local menuFrame = Utility.Create('Frame', {
                    Name = 'Win7PopupMenu',
                    Parent = parentGui,
                    BackgroundColor3 = Color3.fromRGB(240, 240, 240),
                    Position = posUDim2 or UDim2.new(0, 0, 0, 0),
                    Size = UDim2.new(0, menuWidth, 0, totalHeight),
                    Visible = false,
                    ZIndex = zBase,
                })

                Utility.AddStroke(menuFrame, Color3.fromRGB(151, 151, 151), 1, 0, Enum.ApplyStrokeMode.Border)

                local innerWhiteInset = Utility.Create('Frame', {
                    Name = 'MenuInnerWhiteInset',
                    Parent = menuFrame,
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 1, 0, 1),
                    Size = UDim2.new(1, -2, 1, -2),
                    ZIndex = zBase + 1,
                })
                local shadow = Utility.Create('Frame', {
                    Name = 'MenuDropShadow',
                    Parent = menuFrame,
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 0, 0, 0),
                    Size = UDim2.new(1, 0, 1, 0),
                    ZIndex = zBase - 1,
                })

                Utility.Create('Frame', {
                    Name = 'ShadowRightEdge',
                    Parent = shadow,
                    BackgroundColor3 = Color3.fromRGB(0, 0, 0),
                    BackgroundTransparency = 0.72,
                    BorderSizePixel = 0,
                    Position = UDim2.new(1, 1, 0, 3),
                    Size = UDim2.new(0, 2, 1, -1),
                    ZIndex = zBase - 1,
                })
                Utility.Create('Frame', {
                    Name = 'ShadowBottomEdge',
                    Parent = shadow,
                    BackgroundColor3 = Color3.fromRGB(0, 0, 0),
                    BackgroundTransparency = 0.72,
                    BorderSizePixel = 0,
                    Position = UDim2.new(0, 3, 1, 1),
                    Size = UDim2.new(1, -2, 0, 2),
                    ZIndex = zBase - 1,
                })
                Utility.Create('Frame', {
                    Name = 'LeftIconGutterBg',
                    Parent = menuFrame,
                    BackgroundColor3 = Color3.fromRGB(240, 240, 240),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 2, 0, 2),
                    Size = UDim2.new(0, 26, 1, -4),
                    ZIndex = zBase + 1,
                })
                Utility.Create('Frame', {
                    Name = 'GutterSeparatorDark',
                    Parent = menuFrame,
                    BackgroundColor3 = Color3.fromRGB(217, 217, 217),
                    BorderSizePixel = 0,
                    Position = UDim2.new(0, 28, 0, 2),
                    Size = UDim2.new(0, 1, 1, -4),
                    ZIndex = zBase + 2,
                })
                Utility.Create('Frame', {
                    Name = 'GutterSeparatorLight',
                    Parent = menuFrame,
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                    BorderSizePixel = 0,
                    Position = UDim2.new(0, 29, 0, 2),
                    Size = UDim2.new(0, 1, 1, -4),
                    ZIndex = zBase + 2,
                })

                local itemHolder = Utility.Create('Frame', {
                    Name = 'MenuItemsList',
                    Parent = menuFrame,
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 0, 0, 0),
                    Size = UDim2.new(1, 0, 1, 0),
                    ZIndex = zBase + 3,
                })
                local pad = Instance.new('UIPadding')

                pad.PaddingTop = UDim.new(0, 2)
                pad.PaddingBottom = UDim.new(0, 2)
                pad.PaddingLeft = UDim.new(0, 2)
                pad.PaddingRight = UDim.new(0, 2)
                pad.Parent = itemHolder

                local list = Instance.new('UIListLayout')

                list.SortOrder = Enum.SortOrder.LayoutOrder
                list.Padding = UDim.new(0, 0)
                list.Parent = itemHolder

                for idx, item in ipairs(items)do
                    if item.Separator or item == '-' then
                        local sepWrap = Utility.Create('Frame', {
                            Name = 'MenuSeparator_' .. tostring(idx),
                            Parent = itemHolder,
                            BackgroundTransparency = 1,
                            Size = UDim2.new(1, 0, 0, 7),
                            LayoutOrder = idx,
                            ZIndex = zBase + 3,
                        })

                        Utility.Create('Frame', {
                            Name = 'SepLineDark',
                            Parent = sepWrap,
                            BackgroundColor3 = Color3.fromRGB(217, 217, 217),
                            BorderSizePixel = 0,
                            Position = UDim2.new(0, 26, 0, 3),
                            Size = UDim2.new(1, -26, 0, 1),
                            ZIndex = zBase + 4,
                        })
                        Utility.Create('Frame', {
                            Name = 'SepLineLight',
                            Parent = sepWrap,
                            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                            BorderSizePixel = 0,
                            Position = UDim2.new(0, 26, 0, 4),
                            Size = UDim2.new(1, -26, 0, 1),
                            ZIndex = zBase + 4,
                        })
                    else
                        local rowBtn = Utility.Create('TextButton', {
                            Name = 'MenuItem_' .. tostring(item.Text or idx),
                            Parent = itemHolder,
                            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                            BackgroundTransparency = 1,
                            AutoButtonColor = false,
                            Size = UDim2.new(1, 0, 0, 22),
                            LayoutOrder = idx,
                            Text = '',
                            ZIndex = zBase + 4,
                        })

                        Utility.AddCorner(rowBtn, 3)

                        local itemStroke = Utility.AddStroke(rowBtn, Color3.fromRGB(170, 221, 250), 1, 1, Enum.ApplyStrokeMode.Border)
                        local itemGrad = Instance.new('UIGradient')

                        itemGrad.Rotation = 90
                        itemGrad.Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                            ColorSequenceKeypoint.new(0.9, Color3.fromRGB(230, 236, 245)),
                            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
                        })
                        itemGrad.Parent = rowBtn

                        local gutterBox = Utility.Create('Frame', {
                            Name = 'GutterIconBox',
                            Parent = rowBtn,
                            BackgroundColor3 = Color3.fromRGB(230, 236, 245),
                            BackgroundTransparency = (item.Checked == true) and 0.15 or 1,
                            Position = UDim2.new(0, 0, 0, 0),
                            Size = UDim2.new(0, 22, 0, 22),
                            ZIndex = zBase + 5,
                        })

                        Utility.AddCorner(gutterBox, 3)

                        local gutterStroke = Utility.AddStroke(gutterBox, Color3.fromRGB(179, 211, 249), 1, (item.Checked == true) and 0 or 1, Enum.ApplyStrokeMode.Border)
                        local iconOrCheck = Utility.Create('ImageLabel', {
                            Name = 'GutterGlyph',
                            Parent = gutterBox,
                            BackgroundTransparency = 1,
                            Position = UDim2.new(0, 3, 0, 3),
                            Size = UDim2.new(0, 16, 0, 16),
                            Visible = (item.Checked == true) or (item.Icon ~= nil and item.Icon ~= ''),
                            ZIndex = zBase + 6,
                        })

                        if item.Checked ~= nil then
                            Assets.BindIcon(iconOrCheck, 'Checkmark')
                        elseif item.Icon then
                            Assets.BindIcon(iconOrCheck, item.Icon)
                        end

                        Utility.Create('TextLabel', {
                            Name = 'ItemText',
                            Parent = rowBtn,
                            BackgroundTransparency = 1,
                            Position = UDim2.new(0, 30, 0, 0),
                            Size = UDim2.new(1, -90, 1, 0),
                            Font = Theme.Fonts.Regular,
                            Text = tostring(item.Text or 'Command'),
                            TextColor3 = item.Disabled and Theme.Colors.TextDisabled or Theme.Colors.TextPrimary,
                            TextSize = 12,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            ZIndex = zBase + 5,
                        })

                        if item.Shortcut and item.Shortcut ~= '' then
                            Utility.Create('TextLabel', {
                                Name = 'ShortcutText',
                                Parent = rowBtn,
                                BackgroundTransparency = 1,
                                Position = UDim2.new(1, -66, 0, 0),
                                Size = UDim2.new(0, 56, 1, 0),
                                Font = Theme.Fonts.Regular,
                                Text = tostring(item.Shortcut),
                                TextColor3 = item.Disabled and Theme.Colors.TextDisabled or Theme.Colors.TextSecondary,
                                TextSize = 12,
                                TextXAlignment = Enum.TextXAlignment.Right,
                                ZIndex = zBase + 5,
                            })
                        end

                        rowBtn.MouseEnter:Connect(function()
                            if not item.Disabled then
                                rowBtn.BackgroundTransparency = 0.22
                                itemStroke.Transparency = 0
                            end
                        end)
                        rowBtn.MouseLeave:Connect(function()
                            rowBtn.BackgroundTransparency = 1
                            itemStroke.Transparency = 1
                        end)
                        rowBtn.MouseButton1Click:Connect(function()
                            if item.Disabled then
                                return
                            end
                            if item.Checkable or item.Checked ~= nil then
                                item.Checked = not item.Checked
                                iconOrCheck.Visible = item.Checked
                                gutterBox.BackgroundTransparency = item.Checked and 0.15 or 1
                                gutterStroke.Transparency = item.Checked and 0 or 1
