                    end)
                    orb.MouseLeave:Connect(function()
                        hovered = false
                        pressed = false

                        refreshOrb()
                    end)
                    orb.MouseButton1Down:Connect(function()
                        if ctrl.Enabled then
                            pressed = true

                            refreshOrb()
                        end
                    end)
                    orb.MouseButton1Up:Connect(function()
