                local bannerRule = Utility.Create('Frame', {
                    Name = 'BannerDividerLine',
                    Parent = pageHeader,
                    BackgroundColor3 = Theme.Colors.RuleDivider,
                    Position = UDim2.new(0, 0, 1, -2),
