                    return
                end

                local count = #self.ActiveTab.Container:GetChildren() - 1

                if count < 0 then
                    count = 0
                end

                self.ItemCountLabel.Text = tostring(count) .. (count == 1 and ' item' or ' items')
                self.StatusTextLabel.Text = self.ActiveTab.Title .. ' \u{2014} ' .. self.ActiveTab.Subtitle
            end
