                local chevronChevron = Utility.CreateVectorChevron(chevronOrb, expanded and 'Up' or 'Down', Color3.fromRGB(30, 57, 91), chevronOrb.ZIndex + 1)
                local titleLbl = Utility.Create('TextLabel', {
