                    Mode = mode,
                    Active = activeState,
                }

                function controller:SetKey(newKey)
                    self.Value = newKey or Enum.KeyCode.Unknown
                    keyBox.Text = '  ' .. formatKeyName(self.Value)

                    onChanged(self.Value)
