                    table.insert(tabs, tabObj)

                    if #tabs == 1 then
                        selectTab(1)
                    end

                    return tabObj
                end
                function controller:SelectTab(query)
                    if type(query) == 'number' then
                        selectTab(query)
                    elseif type(query) == 'string' then
